curl -s --max-time 25 "https://api.github.com/repos/TownyAdvanced/Towny/releases?per_page=2" $UA | python3 -c "
import sys,json
d=json.load(sys.stdin)
if isinstance(d,dict): print('ERR',str(d)[:200]); sys.exit()
for r in d: 
  print('tag=',r.get('tag_name'),'|',(r.get('published_at') or '')[:10])
  for a in r.get('assets',[])[:5]: print('   ',a['name'],'->',a['browser_download_url'])
"
